package net.officefloor.hq.app;

import java.math.RoundingMode;
import org.springframework.web.bind.annotation.RequestBody;
import net.officefloor.server.http.HttpException;
import net.officefloor.server.http.HttpStatus;
import net.officefloor.web.ObjectResponse;

/**
 * {@code POST /api/invoices/pay} — mark an invoice paid from an {id} body and return the updated row.
 * Wired by {@code officefloor/rest/api/invoices/pay.POST.yml}. Flips the invoice's status to PAID and
 * appends one {@code INVOICE_PAID} audit record (the kept record the request asks for), so the
 * payment can be checked back later through the audit file even though the UI only shows the status.
 */
public class InvoicesPayLogic {

    public void service(@RequestBody PayInvoice body, InvoiceRepository invoices, Audit audit,
            ObjectResponse<Invoice> response) {
        Long id = body.getId();
        if (id == null) {
            throw new HttpException(HttpStatus.BAD_REQUEST, "An invoice id is required");
        }
        Invoice invoice = invoices.findById(id)
                .orElseThrow(() -> new HttpException(HttpStatus.NOT_FOUND, "No such invoice"));
        invoice.setStatus("PAID");
        Invoice saved = invoices.save(invoice);
        String amount = saved.getAmount().setScale(2, RoundingMode.HALF_UP).toPlainString();
        audit.record("INVOICE_PAID id=" + saved.getId() + " amount=" + amount);
        response.send(saved);
    }

    /** Request body for marking an invoice paid. */
    public static class PayInvoice {
        private Long id;

        public Long getId() {
            return id;
        }

        public void setId(Long id) {
            this.id = id;
        }
    }
}

-- Invoices carry a payment status so a project's detail page can show UNPAID/PAID and mark one paid.
-- New invoices default to UNPAID; existing rows adopt the same default via the column default.
ALTER TABLE invoices ADD COLUMN status VARCHAR(16) NOT NULL DEFAULT 'UNPAID';

import { InvoiceListToolbar } from '../../slots/defs/invoiceListToolbar';
import { useSearchParam, asString } from '../../url/useSearchParam';
import { formatMoney } from '../../ui/money';
import { useInvoices, usePayInvoice } from './invoices';

// A project's invoices and what they add up to. Reads its own query key (scoped to the project) and
// derives the total from the rows — the aggregate is never stored, so it always matches the list.
// Each row shows its payment status and, while UNPAID, a control to mark it paid. The ordering comes
// from the shared `invoiceSort` URL key (set by a toolbar control), so the server returns the rows
// already in order.
export function InvoiceList({ projectId }: { projectId: number }) {
  const [sort] = useSearchParam('invoiceSort', asString);
  const { data: invoices } = useInvoices(projectId, sort || undefined);
  const pay = usePayInvoice(projectId);

  if (!invoices) {
    return null;
  }

  const total = invoices.reduce((sum, invoice) => sum + Number(invoice.amount), 0);

  return (
    <>
    <InvoiceListToolbar.Slot projectId={projectId} />
    <table data-testid="project-invoices-table">
      <thead>
        <tr>
          <th>Amount</th>
          <th>Issued</th>
          <th>Due</th>
          <th>Status</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        {invoices.map((invoice) => (
          <tr key={invoice.id} data-testid={`invoice-row-${invoice.id}`}>
            <td data-testid="invoice-amount">{formatMoney(invoice.amount)}</td>
            <td data-testid="invoice-issued">{invoice.issuedDate}</td>
            <td data-testid="invoice-due">{invoice.dueDate}</td>
            <td data-testid="invoice-status">{invoice.status}</td>
            <td>
              {invoice.status !== 'PAID' && (
                <button
                  type="button"
                  data-testid={`invoice-pay-${invoice.id}`}
                  disabled={pay.isPending}
                  onClick={() => pay.mutate({ id: invoice.id })}
                >
                  Mark paid
                </button>
              )}
            </td>
          </tr>
        ))}
      </tbody>
      <tfoot>
        <tr>
          <td data-testid="project-invoices-total">{formatMoney(total)}</td>
        </tr>
      </tfoot>
    </table>
    </>
  );
}

